(function ($) {
    "use strict";

    // Toggle sidebar on mobile / via topbar toggler
    function toggleSidebar(e) {
        e.preventDefault();
        $("body").toggleClass("sidebar-toggled");
    }

    window.initSbAdmin = function () {
        $("#sidebarToggle, #sidebarToggleTop").on("click", toggleSidebar);

        // Scroll to top behavior
        var scrollToTop = $(".scroll-to-top");
        $(window).scroll(function () {
            if ($(this).scrollTop() > 100) {
                scrollToTop.fadeIn(100);
            } else {
                scrollToTop.fadeOut(100);
            }
        });
        scrollToTop.on("click", function (e) {
            e.preventDefault();
            $("html,body").animate({ scrollTop: 0 }, 300);
        });

        // Enable Bootstrap dropdowns (hover on desktop for sidebar)
        $(".sidebar .nav-link[data-bs-toggle='dropdown']").each(function () {
            $(this).dropdown();
        });
    };

    $(window).on("load", window.initSbAdmin);
})(jQuery);
